"""Every rounding rule of meterbill lives here."""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _round_fraction(x: Fraction, method: str) -> int:
    """The integer nearest to `x` (a magnitude, not negative) by `method`."""
    q, r = divmod(x.numerator, x.denominator)
    twice = 2 * r
    if method == HALF_UP:
        up = twice >= x.denominator
    elif method == HALF_EVEN:
        up = twice > x.denominator or (twice == x.denominator and q % 2 == 1)
    else:
        up = False
    return q + 1 if up else q


def _build(negative: bool, coefficient: int, exponent: int) -> Decimal:
    return Decimal((1 if negative else 0, tuple(int(c) for c in str(coefficient)), exponent))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    step_exp = step.as_tuple().exponent
    unit = Fraction(step)
    n = _round_fraction(abs(Fraction(value)) / unit, method)
    sign = value.is_signed()
    # the multiple, with the exponent of `step`
    multiple = Fraction(n) * unit / Fraction(Decimal(1).scaleb(step_exp))
    return _build(sign, int(multiple), step_exp)


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    exact = sum((Fraction(a) for a in amounts), Fraction(0))
    whole = round_amount(_decimal_of(exact), step, HALF_UP) if amounts else None
    parts = [round_amount(a, step, DOWN) for a in amounts]
    if not amounts:
        return []
    zero = _build(False, 0, step.as_tuple().exponent)
    rest = whole - sum(parts, zero)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] += rest
            break
    return parts


def _decimal_of(x: Fraction) -> Decimal:
    """A Fraction that is a finite decimal, as an exact Decimal."""
    den = x.denominator
    e = 0
    while den % 10 == 0 or den % 2 == 0 or den % 5 == 0:
        if den % 10 == 0:
            den //= 10
        elif den % 2 == 0:
            den //= 2
            x *= 5
            continue
        else:
            den //= 5
            x *= 2
            continue
        e += 1
    return _build(x < 0, abs(int(x * 10 ** e)), -e)


def legacy_cents(value: float, places: int = 2) -> float:
    if not isinstance(places, int) or not 0 <= places <= 6:
        raise ValueError("places must be from 0 to 6")
    factor = 10 ** places
    return math.floor(value * factor + 0.5) / factor


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    if not isinstance(places, int) or places < 0:
        raise ValueError("places must not be negative")
    if isinstance(value, Decimal):
        if not value.is_finite():
            return str(value)
        out = round_amount(value, Decimal(1).scaleb(-places), method)
        return _plain(out, places)
    if not isinstance(value, float):
        raise TypeError("value must be a float or a Decimal")
    if method != HALF_EVEN:
        raise ValueError("a float is only written half to even")
    return format(value, f".{places}f")


def _plain(d: Decimal, places: int) -> str:
    sign, digits, _ = d.as_tuple()
    text = "".join(map(str, digits)).rjust(places + 1, "0")
    if places:
        text = text[:-places] + "." + text[-places:]
    return ("-" if sign else "") + text
EOF

